Lemma ieq_split : forall k lo hi lo' hi' mlo mhi,
  0 <= lo < 2^k -> 0 <= lo' < 2^k -> 0 <= mlo < 2^k -> 0 <= hi -> 0 <= hi' -> 0 <= mhi -> 0 <= k ->
  Z.land (Z.lxor (lo + hi * 2^k) (lo' + hi' * 2^k)) (mlo + mhi * 2^k)
  = Z.land (Z.lxor lo lo') mlo + Z.land (Z.lxor hi hi') mhi * 2^k.
