Lemma sum_pow2_zero : forall a b k, 0 <= a -> 0 <= b -> 0 <= k -> (a + b * 2^k = 0 <-> a = 0 /\ b = 0).
Proof. intros a b k Ha Hb Hk. assert (0 < 2^k) by (apply Z.pow_pos_nonneg; lia). nia. Qed.

Lemma land_lxor_nonneg : forall a b m, 0 <= m -> 0 <= Z.land (Z.lxor a b) m.
Proof. intros. apply Z.land_nonneg. right. lia. Qed.

