Lemma dig1_acc : forall r c, 0 <= r < 2^32 -> 0 <= c < 256 ->
  Z_to_bv 64 (bv_swrap 32 (bv_unsigned (Z_to_bv 64 (Z.shiftl (bv_unsigned (Z_to_bv 64 (bv_swrap 32 r))) 2 + bv_swrap 32 r))
                           + bv_unsigned (Z_to_bv 64 (Z.lor (bv_unsigned (Z_to_bv 64 c)) 32))))
  = Z_to_bv 64 (bv_swrap 32 ((5 * r + Z.lor c 32) mod 2^32)).
